from pathlib import Path
exec((Path(__file__).with_name('material_sort.py')).read_text().split('with sync_playwright() as p:')[0])
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for path in ['/#material','/prototype-vgp.html#material']:
  page=b.new_page(viewport={'width':390,'height':844});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.route('**/cloud-config.js',lambda r:r.fulfill(body='window.VGP_CLOUD={enabled:false};',content_type='text/javascript'));page.add_init_script('if(!localStorage.getItem("vgp-prototype-v1"))localStorage.setItem("vgp-prototype-v1",'+json.dumps(json.dumps(source))+');');page.goto('http://127.0.0.1:8000'+path);page.locator('[data-bulk-toggle]').click();page.locator('[data-bulk-equipment="sort-fictif-1"]').check();page.locator('#search').fill('Alpha');expect(page.locator('[data-bulk-count]')).to_contain_text('1 hors de la liste');page.locator('[data-bulk-all]').click();expect(page.locator('[data-bulk-count]')).to_contain_text('2 sélectionné');page.locator('[data-bulk-assign]').click();dialog=page.locator('#bulkOwnersDialog');expect(dialog).to_be_visible();dialog.locator('[name=owner]').select_option('Alice fictive');dialog.get_by_role('button',name='Associer la sélection',exact=True).click();expect(dialog).not_to_be_visible();expect(page.locator('#message')).to_contain_text('1 équipement(s) associé(s) à Alice fictive · 1 déjà associé(s)');expect(page.locator('#search')).to_have_value('Alpha');saved=json.loads(page.evaluate('localStorage.getItem("vgp-prototype-v1")'));assert saved['equipment'][0]['owner']=='Zoé fictive' and saved['equipment'][0]['additionalOwners']==['Alice fictive'];assert saved['equipment'][1]['owner']=='Alice fictive';assert saved['equipment'][2]['owner']=='';assert all(e['controls']==old['controls'] and e['months']==old['months'] for e,old in zip(saved['equipment'],source['equipment']))
  # Nouvelle sélection ; une réaffectation concurrente doit être relue avant validation.
  page.locator('#search').fill('');page.locator('[data-bulk-toggle]').click();page.locator('[data-bulk-equipment="sort-fictif-3"]').check();page.locator('[data-bulk-assign]').click();dialog.locator('[name=owner]').select_option('Alice fictive');changed=json.loads(json.dumps(saved));changed['equipment'][2]['owner']='Zoé fictive';page.evaluate('(s)=>localStorage.setItem("vgp-prototype-v1",JSON.stringify(s))',changed);dialog.get_by_role('button',name='Associer la sélection',exact=True).click();expect(dialog.locator('[data-bulk-error]')).to_contain_text('ont changé');assert json.loads(page.evaluate('localStorage.getItem("vgp-prototype-v1")'))==changed
  # Échec d’enregistrement : conserver sélection, propriétaire et dialogue.
  page.evaluate("()=>{window.oldSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(){throw new DOMException('full','QuotaExceededError')}}");dialog.get_by_role('button',name='Associer la sélection',exact=True).click();expect(dialog.locator('[data-bulk-error]')).to_contain_text('Enregistrement impossible');expect(dialog).to_be_visible();expect(dialog.locator('[name=owner]')).to_have_value('Alice fictive');expect(page.locator('[data-bulk-count]')).to_contain_text('1 sélectionné');page.evaluate('()=>{Storage.prototype.setItem=window.oldSetItem}');dialog.get_by_role('button',name='Associer la sélection',exact=True).click();expect(dialog).not_to_be_visible();final=json.loads(page.evaluate('localStorage.getItem("vgp-prototype-v1")'));assert final['equipment'][2]['owner']=='Zoé fictive' and final['equipment'][2]['additionalOwners']==['Alice fictive'];page.reload();expect(page.locator('[data-bulk-toggle]')).to_have_attribute('aria-pressed','false');assert json.loads(page.evaluate('localStorage.getItem("vgp-prototype-v1")'))==final;assert page.evaluate('document.documentElement.scrollWidth')==390;assert not errors,errors;page.close()
 # Accès lecteur : aucun bouton permettant une association et aucun appel d’écriture.
 config="window.VGP_CLOUD={enabled:true,url:'https://test.supabase.co',publicKey:'sb_publishable_test',workspaceId:'10000000-0000-0000-0000-000000000001'};document.documentElement.classList.add('cloud-locked');"
 def api(route):
  headers={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'apikey,authorization,content-type','Access-Control-Allow-Methods':'POST'}
  if route.request.method=='OPTIONS':route.fulfill(status=204,headers=headers);return
  url=route.request.url
  if '/token?' in url:result={'access_token':'test','refresh_token':'test','expires_in':3600}
  elif url.endswith('read_shift_calendar'):result={'revision':0,'rows':[],'imports':[]}
  elif url.endswith('read_state'):result={'revision':1,'payload':source,'role':'reader'}
  else:raise AssertionError(url)
  route.fulfill(json=result,headers=headers)
 context=b.new_context();context.route('**/cloud-config.js',lambda r:r.fulfill(body=config,content_type='text/javascript'));context.route('https://test.supabase.co/**',api);page=context.new_page();page.goto('http://127.0.0.1:8000/#material');page.locator('#loginForm [name=email]').fill('reader@example.test');page.locator('#loginForm [name=password]').fill('test');page.locator('#loginForm button').first.click();expect(page.locator('#materialView')).to_be_visible();expect(page.locator('[data-bulk-toggle]')).to_be_disabled();context.close();b.close()
